mapper.select:
SELECT c.id AS change_id, c.change_no, c.user_id, u.phone AS user_phone, old_item.order_id, o.order_no, c.old_order_item_id, c.new_order_item_id, old_train.train_no AS old_train_no, new_train.train_no AS new_train_no, c.original_amount, c.new_amount, c.difference_amount, c.difference_type, c.status, c.expire_at, c.confirmed_at, c.cancelled_at, c.created_at FROM change_record c JOIN order_item old_item ON old_item.id = c.old_order_item_id JOIN ticket_order o ON o.id = old_item.order_id JOIN user u ON u.id = c.user_id JOIN train_run old_run ON old_run.id = old_item.run_id JOIN train old_train ON old_train.id = old_run.train_id JOIN order_item new_item ON new_item.id = c.new_order_item_id JOIN train_run new_run ON new_run.id = new_item.run_id JOIN train new_train ON new_train.id = new_run.train_id WHERE 1 = 1 AND c.change_no LIKE CONCAT('%', #{changeNo}, '%') AND o.order_no LIKE CONCAT('%', #{orderNo}, '%') AND c.status = #{status}
AND (old_train.train_no LIKE CONCAT('%', #{trainNo}, '%') OR new_train.train_no LIKE CONCAT('%', #{trainNo}, '%'))
AND c.created_at >= #{startDate} AND c.created_at < DATE_ADD(#{endDate}, INTERVAL 1 DAY) ORDER BY c.created_at DESC, c.id DESC
